class Solution {
public:
    vector<int> sortEvenOdd(vector<int>& nums) {
        vector<int> a,b;
        for(int i=0;i<(int)nums.size();++i) (i%2?b:a).push_back(nums[i]);
        sort(a.begin(),a.end());sort(b.rbegin(),b.rend());
        for(int i=0;i<(int)nums.size();++i) nums[i]=(i%2?b[i/2]:a[i/2]);
        return nums;
    }
};
